using System;using System.Globalization;using System.Linq;using ForteMove.Models.Operations;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Driver{public partial class PreTripCheck:DriverPage{private long Id{get{long x;return long.TryParse(Request.QueryString["id"],out x)?x:0;}}protected void Page_Load(object sender,EventArgs e){if(!IsPostBack)LoadContext();}private void LoadContext(){var d=ServiceFactory.CreateDriverOperationsService().GetTripDetails(CurrentPrincipalContext.UserAccountId,Id);if(d==null){Response.Redirect(ResolveUrl("~/Driver/Today.aspx"),true);return;}if(!string.IsNullOrEmpty(d.DepartureAvailabilityMessage)){litError.Text=Server.HtmlEncode(d.DepartureAvailabilityMessage);pnlError.Visible=true;btnConfirm.Enabled=false;}litContext.Text=Server.HtmlEncode(d.TripCode+" · "+d.RouteName+" · Bus "+d.FleetNumber);hidTripRv.Value=Convert.ToBase64String(d.TripRowVersion);hidAssignmentRv.Value=Convert.ToBase64String(d.AssignmentRowVersion);txtOdometer.Text=d.BusOdometerKilometres.ToString("0.0",CultureInfo.InvariantCulture);}protected void btnConfirm_Click(object sender,EventArgs e){decimal value;decimal? odo=decimal.TryParse(txtOdometer.Text,NumberStyles.Number,CultureInfo.InvariantCulture,out value)?value:(decimal?)null;var result=ServiceFactory.CreateDriverOperationsService().ConfirmReadiness(new ConfirmReadinessRequest{TripId=Id,ExteriorConditionChecked=chkExterior.Checked,TyresSafeChecked=chkTyres.Checked,LightsIndicatorsChecked=chkLights.Checked,NoCriticalDashboardWarningsChecked=chkDashboard.Checked,DoorsOperationalChecked=chkDoors.Checked,EmergencyEquipmentPresentChecked=chkEmergency.Checked,NoBlockingNewDefectChecked=chkDefects.Checked,StartOdometerKilometres=odo,TripRowVersion=Parse(hidTripRv.Value),AssignmentRowVersion=Parse(hidAssignmentRv.Value)},CurrentPrincipalContext.UserAccountId);if(result.Succeeded){Response.Redirect(ResolveUrl("~/Driver/TripDetails.aspx?id="+Id),true);return;}litError.Text=Server.HtmlEncode(string.Join(" ",result.Errors.Select(x=>x.Message)));pnlError.Visible=true;LoadContext();}private static byte[] Parse(string x){try{return Convert.FromBase64String(x);}catch{return null;}}}}
